#include <wimlib.h>
#include <stdio.h>
#include <stdlib.h>
static int entry(const struct wimlib_resource_entry*e,void*p){(void)p;printf("resource %llu %llu %llu %u %u %u%u%u%u%u%u %llu %llu %llu ",(unsigned long long)e->uncompressed_size,(unsigned long long)e->compressed_size,(unsigned long long)e->offset,e->part_number,e->reference_count,e->is_compressed,e->is_metadata,e->is_free,e->is_spanned,e->is_missing,e->packed,(unsigned long long)e->raw_resource_offset_in_wim,(unsigned long long)e->raw_resource_compressed_size,(unsigned long long)e->raw_resource_uncompressed_size);for(unsigned i=0;i<20;i++)printf("%02x",e->sha1_hash[i]);puts("");return 0;}
static void value(const char*label,const char*value){printf("%s ",label);if(value)for(const unsigned char*p=(const unsigned char*)value;*p;p++)printf("%02x",*p);else printf("NULL");puts("");}
static void state(WIMStruct*w,const char*label){struct wimlib_wim_info i;wimlib_get_wim_info(w,&i);printf("state %s %u %u %u\n",label,i.image_count,i.boot_index,i.has_rpfix);for(unsigned j=1;j<=i.image_count;j++){printf("image %u\n",j);value("name",wimlib_get_image_name(w,j));value("description",wimlib_get_image_description(w,j));value("wimboot",wimlib_get_image_property(w,j,"WIMBOOT"));}printf("lookup %d\n",wimlib_iterate_lookup_table(w,0,entry,NULL));}
int main(int argc,char**argv){if(argc!=6)return 2;int flags=atoi(argv[2]),image=atoi(argv[3]),mode=atoi(argv[4]);WIMStruct*source=NULL,*dest=NULL;int r=wimlib_open_wim(argv[1],0,&source);printf("open %d\n",r);if(r)return 0;wimlib_create_new_wim(0,&dest);wimlib_add_empty_image(source,"Pending",NULL);const char*name=NULL,*desc=NULL;switch(mode){case 1:name="Renamed";desc="Overridden";break;case 2:name="";desc="";break;case 3:name="bad\1";break;case 4:name="First";wimlib_add_empty_image(dest,"First",NULL);break;}
 r=wimlib_export_image(source,image,dest,name,desc,flags);printf("export %d\n",r);state(source,"source");state(dest,"dest");if(!r){printf("repeat %d\n",wimlib_export_image(source,image,dest,NULL,NULL,flags&~8));if(image!=-1)printf("back %d\n",wimlib_export_image(dest,1,source,NULL,NULL,2));printf("verify-source %d\n",wimlib_verify_wim(source,0));}wimlib_free(source);printf("verify-dest %d\n",wimlib_verify_wim(dest,0));if(!r)printf("write %d\n",wimlib_write(dest,argv[5],-1,0,1));wimlib_free(dest);return 0;}
